// Localisation: the source copy is Traditional Chinese; Simplified Chinese and
// English live in i18n-data.js (generated by scripts/gen-i18n.py).
//
// Any system language that is not Chinese falls back to English.

import { TRANSLATIONS } from './i18n-data.js';

const SUPPORTED = ['zh-Hant', 'zh-Hans', 'en'];
const ATTRS = ['title', 'aria-label', 'placeholder', 'data-tip', 'alt'];

let locale = 'zh-Hant';
let dict = null;
let patterns = [];
let observer = null;
let pending = 0;

/** Pick the UI language from the system locale list. */
export function detectLocale(override) {
  const forced = normaliseOverride(override);
  if (forced) return forced;
  const list =
    (typeof navigator !== 'undefined' && (navigator.languages?.length ? navigator.languages : [navigator.language])) ||
    [];
  for (const raw of list) {
    const tag = String(raw || '')
      .toLowerCase()
      .replace(/_/g, '-');
    if (!tag) continue;
    if (tag.startsWith('zh')) {
      if (/(hant|tw|hk|mo)/.test(tag)) return 'zh-Hant';
      if (/(hans|cn|sg|my)/.test(tag)) return 'zh-Hans';
      return 'zh-Hant'; // plain "zh": keep the original Traditional copy
    }
    // Everything else (including CJK-adjacent locales we do not ship) -> English.
    return 'en';
  }
  return 'en';
}

function normaliseOverride(value) {
  const v = String(value || '').trim().toLowerCase().replace(/_/g, '-');
  if (!v) return '';
  if (v === 'en' || v.startsWith('en-')) return 'en';
  if (v === 'zh-hans' || v === 'zh-cn' || v === 'zh-sg' || v === 'zh-hans-cn') return 'zh-Hans';
  if (v === 'zh-hant' || v === 'zh-tw' || v === 'zh-hk' || v === 'zh-mo') return 'zh-Hant';
  return '';
}

function escapeRe(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** Compile "…${name}…" keys into regexes so interpolated runtime strings
 *  ("Tool: Brush", "3 images") still translate. */
function buildPatterns(map) {
  const out = [];
  if (!map) return out;
  for (const [key, value] of Object.entries(map)) {
    if (!key.includes('${')) continue;
    const names = [];
    let source = '^';
    let last = 0;
    const re = /\$\{([^}]+)\}/g;
    let m;
    while ((m = re.exec(key))) {
      source += escapeRe(key.slice(last, m.index)) + '([\\s\\S]+?)';
      names.push(m[1]);
      last = m.index + m[0].length;
    }
    source += escapeRe(key.slice(last)) + '$';
    out.push({ re: new RegExp(source), names, value });
  }
  return out;
}

/** Translate one UI string. Unknown strings (file names, user text) pass
 *  through untouched, so this is safe to call on arbitrary content. */
export function tr(text) {
  if (!dict || typeof text !== 'string' || !text) return text;
  const hit = dict[text];
  if (hit != null) return hit;
  for (const p of patterns) {
    const m = p.re.exec(text);
    if (!m) continue;
    let result = p.value;
    p.names.forEach((name, i) => {
      const raw = m[i + 1];
      const translated = tr(raw); // nested values like tool names
      result = result.split('${' + name + '}').join(translated);
    });
    return result;
  }
  return text;
}

function translateTextNode(node) {
  const raw = node.nodeValue;
  if (!raw) return;
  const trimmed = raw.trim();
  if (!trimmed || trimmed.length > 240) return;
  const next = tr(trimmed);
  if (next === trimmed) return;
  const start = raw.indexOf(trimmed);
  node.nodeValue = raw.slice(0, start) + next + raw.slice(start + trimmed.length);
}

function translateAttrs(el) {
  if (!el || el.nodeType !== 1) return;
  for (const attr of ATTRS) {
    if (!el.hasAttribute(attr)) continue;
    const raw = el.getAttribute(attr);
    if (!raw) continue;
    const next = tr(raw);
    if (next !== raw) el.setAttribute(attr, next);
  }
}

/** Translate a subtree (defaults to the whole document). Idempotent. */
export function applyDom(root = document.body) {
  if (!dict || !root) return;
  if (root.nodeType === 3) {
    translateTextNode(root);
    return;
  }
  if (root.nodeType === 1) translateAttrs(root);
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT, {
    acceptNode(node) {
      if (node.nodeType === 1) {
        const tag = node.tagName;
        if (tag === 'SCRIPT' || tag === 'STYLE') return NodeFilter.FILTER_REJECT;
        return NodeFilter.FILTER_SKIP; // still visit children
      }
      return NodeFilter.FILTER_ACCEPT;
    },
  });
  let node = walker.nextNode();
  while (node) {
    translateTextNode(node);
    node = walker.nextNode();
  }
  // element attributes: walk elements separately (TreeWalker skips them above)
  const els = root.querySelectorAll?.('*') || [];
  for (const el of els) translateAttrs(el);
  if (root.nodeType === 1) translateAttrs(root);
}

function scheduleApply() {
  if (pending) return;
  pending = window.setTimeout(() => {
    pending = 0;
    applyDom(document.body);
  }, 40);
}

/** Initialise locale + translate the current DOM, then keep new nodes in sync. */
export function initI18n(options = {}) {
  const { override = '' } = options;
  locale = detectLocale(override);
  dict = TRANSLATIONS[locale] || null;
  patterns = buildPatterns(dict);
  document.documentElement.lang = locale === 'zh-Hans' ? 'zh-Hans' : locale;
  applyDom(document);
  if (typeof MutationObserver !== 'undefined' && !observer) {
    observer = new MutationObserver(scheduleApply);
    observer.observe(document.body, {
      childList: true,
      subtree: true,
      characterData: true,
      attributes: true,
      attributeFilter: ATTRS,
    });
  }
  window.LumenI18n = { locale, tr, apply: applyDom, supported: SUPPORTED };
  return locale;
}

export function getLocale() {
  return locale;
}
